examples.code:
:root { --page: #f6f7fb; --surface: #fff; --ink: #202839; --accent: #3153c7; --edge: #c7cedd; }
.panel { color: var(--ink); background: var(--surface); border: 1px solid var(--edge); border-radius: 1rem; }
.panel a { color: var(--accent); text-decoration: underline; text-underline-offset: .2em; }
